6|/**
7| * V5 Phase P02 § V5-4 — canonical `Claim`/`Evidence` definitions.
8| *
9| * Per the phase doc: this phase owns the canonical Evidence/Claim definitions; Phase 07 only
10| * adds the behavioral edge types (SUPPORTS/CONTRADICTS/VALIDATES/THREATENS/PRESERVES) and
11| * ClaimVerifier on top of these two entities — so this phase defines and stores the entities; it does NOT build the
12| * claim-evidence graph traversal / `ClaimVerifier` (that's Phase 07's job). The one enforcement
13| * this phase does own: a required `Claim` cannot be finalized with zero evidence references —
14| * see `ClaimStore.finalizeClaim`.
15| */
16|export type ClaimSource = 'ACCEPTANCE_CRITERION' | 'PATCH_INTENT' | 'FINAL_RESPONSE' | 'INVARIANT';
17|
18|export type Claim = {
19|  claimId: string;
20|  taskId: string;
21|  statement: string;
22|  source: ClaimSource;
23|  required: boolean;
24|  /** Set once `finalizeClaim` succeeds. Empty until then. */
25|  evidenceIds: string[];
26|  finalized: boolean;
27|};
28|
29|export type EvidenceType =
30|  | 'SOURCE'
31|  | 'SYMBOL_RELATION'
32|  | 'TEST'
33|  | 'BUILD'
34|  | 'DIAGNOSTIC'
35|  | 'DIFF'
36|  | 'RUNTIME'
37|  | 'USER_CONFIRMATION';
38|
39|export type EvidenceResult = 'SUPPORTING' | 'CONTRADICTING' | 'NEUTRAL';
40|
41|export type Evidence = {
42|  evidenceId: string;
43|  taskId: string;
44|  type: EvidenceType;
45|  subjectRefs: string[];
46|  result: EvidenceResult;
47|  artifactRef?: string;
48|  /**
49|   * Grounding — EV-2/EV-3 (p-60, echoed in this phase doc): must distinguish "evidence from a
50|   * real model decision" from "evidence replayed from a scripted/mock provider fixture" so a
51|   * mock-provider replay (see P00's `MUST-REVALIDATE-WITH-REAL-MODEL.md`) can never silently
52|   * pass as live-model-grounded evidence. Every `sourceRefs` entry produced by the current
53|   * mock-provider corpus is tagged `provider:mock` — a real live run will tag `provider:live`.
54|   */
55|  sourceRefs: string[];
56|  producedAt: string;
57|};
58|
59|export class ClaimStore {
60|  private readonly claims = new Map<string, Claim>();
61|
62|  create(params: { taskId: string; statement: string; source: ClaimSource; required: boolean }): Claim {
63|    const claim: Claim = {
64|      claimId: randomUUID(),
65|      taskId: params.taskId,
66|      statement: params.statement,
67|      source: params.source,
68|      required: params.required,
69|      evidenceIds: [],
70|      finalized: false,
71|    };
72|    this.claims.set(claim.claimId, claim);
73|    return claim;
74|  }
75|
76|  get(claimId: string): Claim | undefined {
77|    return this.claims.get(claimId);
78|  }
79|
80|  list(): Claim[] {
81|    return [...this.claims.values()];
82|  }
83|
84|  /**
85|   * The one real enforcement this phase owns (doc DoD: the agent's final answer must not
86|   * record a required claim without an evidence reference). A required claim with zero evidence references
87|   * is refused — the caller (`AgentOrchestrator`) must treat that as an unmet acceptance
88|   * criterion, not silently finalize the task as complete.
89|   */
90|  finalizeClaim(claimId: string, evidenceIds: string[]): { ok: true } | { ok: false; reason: string } {
91|    const claim = this.claims.get(claimId);
92|    if (!claim) {
93|      return { ok: false, reason: 'claim_not_found' };
94|    }
95|    if (claim.required && evidenceIds.length === 0) {
96|      return { ok: false, reason: 'required_claim_missing_evidence' };
97|    }
98|    this.claims.set(claimId, { ...claim, evidenceIds, finalized: true });
99|    return { ok: true };
100|  }
101|}
102|
103|export class EvidenceStore {
104|  private readonly evidence: Evidence[] = [];
105|
106|  record(params: {
107|    taskId: string;
108|    type: EvidenceType;
109|    subjectRefs: string[];
110|    result: EvidenceResult;
111|    artifactRef?: string;
112|    sourceRefs: string[];
113|  }): Evidence {
114|    const item: Evidence = {
115|      evidenceId: randomUUID(),
116|      taskId: params.taskId,
117|      type: params.type,
118|      subjectRefs: params.subjectRefs,
119|      result: params.result,
120|      artifactRef: params.artifactRef,"
}
